/* GuroPrep JHS Science (Grades 7–10). Loads after src/science/items-and-activities-g3-6-term3.js (SCIB, s_bank). Keys are grade-term-index. */
/* ===================== JHS Science Grade 7: item banks and activities (key = grade-term-index) ===================== */
Object.assign(SCIB,{
'7-1-0':{F:[["Why do scientists use models?","to explain things that are too small, large, or hidden to observe directly","to make science harder","to replace all experiments","to decorate classrooms"],["Which is a model?","a globe of the Earth","a real volcano","an actual atom","the Sun itself"],"Give one example of a model used in science.|Examples: globe, diagram of an atom, map, model of the solar system.",["A diagram of the water cycle is a model because it ____.","shows a process we cannot see all at once","is the real water cycle","is made of water","is always perfect"]],
 C:["Why can a model never be exactly like the real thing?|It is simplified; it leaves out some details to make the idea easier to understand.","Why do scientists change models over time?|New evidence may show the old model is incomplete or wrong.",["Which phenomenon needs a model because it cannot be seen directly?","the movement of particles in air","a falling mango","a moving jeepney","a growing plant"],"Name two kinds of models.|physical (3D), diagram/drawing, mathematical, computer simulation (any two)"],
 E:["Evaluate a model: a ball-and-stick model of a molecule. What does it show well and what does it leave out?|It shows how atoms are connected; it does not show true sizes, motion, or electron clouds.","Design a simple model to explain why we see a rainbow. What will you use?|Answers vary; e.g., a glass of water and a flashlight to show light bending into colors.","How did the model of the atom change over time? Why is this an example of how science works?|It changed from a solid sphere to a nucleus with electron shells as new evidence was found; science revises models."],
 act:'In groups, make a simple model of something you cannot see directly (e.g., particles in a solid, liquid and gas using beads or seeds). Explain what your model shows and what it leaves out.'},
'7-1-1':{F:[["According to the particle model, all matter is made up of ____.","tiny particles","water","air only","cells"],["Each pure substance has ____.","its own kind of particles","the same particles as all other substances","no particles","only liquid particles"],"Is air made of particles?|Yes.",["Sugar and salt look similar, but they are different substances because ____.","they are made of different kinds of particles","one is a solid","they are white","they dissolve"]],
 C:["Why does the smell of cooking adobo spread through the house? Use the particle model.|Particles of the smell move and spread through the air to your nose.","How does the particle model explain why sugar disappears in water?|Sugar particles spread out between water particles; they are too small to see.",["Which is a pure substance?","distilled water","seawater","air","soil"],"What is the difference between particles of a pure substance and a mixture?|A pure substance has one kind of particle; a mixture has two or more kinds."],
 E:["Use the particle model to explain why a balloon shrinks over a few days.|Gas particles slowly escape through tiny spaces in the balloon material.","Why can 50 mL of alcohol and 50 mL of water mixed together give less than 100 mL?|The particles fit into the spaces between each other.","Explain how the particle model helps explain diffusion of food coloring in water.|Particles of the coloring and water move and mix until evenly spread."],
 act:'Drop food coloring into a glass of hot water and a glass of cold water. Observe and draw how the color spreads. Explain using the particle model.'},
'7-1-2':{F:[["Particles of matter are always ____.","moving","still","growing","melting"],["What happens to particles when they are heated?","they move faster","they stop","they get bigger","they disappear"],["Between particles there are ____.","spaces","no gaps","other materials always","water"],"Do particles attract each other?|Yes."],
 C:["Why does a sealed bottle of soda fizz more when it is warm?|Gas particles move faster when warm and escape more easily.","Explain why a dent in a ping-pong ball can pop out in hot water.|Air particles inside move faster and push harder on the walls, so the ball expands.",["Which shows that particles have spaces between them?","sugar dissolving in water without overflowing a full glass","ice floating","a rock falling","paper burning"],"Why are particles in a solid held in place?|Strong attraction between particles keeps them close and fixed."],
 E:["Explain why railroad tracks have small gaps between sections.|Heat makes particles move faster and spread out, so the metal expands; gaps prevent bending.","Compare particle motion in cold and hot water using a diagram description.|Hot water: particles move fast and far; cold water: particles move slowly.","How does the particle model explain why perfume smell reaches you faster in a warm room?|Particles move faster at higher temperature, so they diffuse faster."],
 act:'Put the same amount of sugar in hot water and in cold water without stirring. Time how long it takes to dissolve. Explain the results using particle motion.'},
'7-1-3':{F:[["In which state are particles closely packed in a fixed pattern?","solid","liquid","gas","plasma only"],["In which state do particles move freely and are far apart?","gas","solid","liquid","ice"],["In a liquid, particles are ____.","close together but can slide past each other","fixed in place","very far apart","not moving"],"Which state has a fixed shape and volume?|solid"],
 C:["Why can liquids take the shape of their container?|Their particles can slide past each other.","Why can gases be compressed easily?|There are large spaces between gas particles.",["Which diagram describes a gas?","particles far apart, moving in all directions","particles in rows, vibrating","particles touching, sliding","particles stuck together"],"Describe how particles move in a solid.|They vibrate in fixed positions."],
 E:["Draw (describe) the particles of ice, water, and water vapor. What changes from one to the next?|Spacing and motion increase from ice to water to vapor; arrangement goes from orderly to random.","Why is it hard to compress a liquid but easy to compress a gas?|Liquid particles are already close together; gas particles have large spaces.","Explain why a gas fills any container.|Gas particles move freely and spread out to fill the space."],
 act:'Use beads or seeds on a tray to model a solid, a liquid, and a gas. Shake the tray gently, then harder. Draw the arrangement and motion for each state.'},
'7-1-4':{F:[["The change from solid to liquid is ____.","melting","freezing","evaporation","condensation"],["The change from liquid to gas is ____.","evaporation (boiling)","condensation","melting","freezing"],["The change from gas to liquid is ____.","condensation","melting","evaporation","sublimation"],["The change from liquid to solid is ____.","freezing","melting","boiling","evaporation"]],
 C:["Is heat absorbed or released when ice melts? Explain using particles.|Absorbed; particles gain energy, move more, and break from fixed positions.","Why do water droplets form on the outside of a cold glass?|Water vapor particles in the air lose energy on the cold surface and condense into liquid.","What happens to particle arrangement when water freezes?|Particles slow down and arrange into a fixed pattern.",["During boiling, the energy added is used to ____.","separate particles into gas","make particles smaller","stop particle motion","change the color"]],
 E:["Explain why sweating cools the body, using particle model and energy.|Sweat evaporates; the fastest particles escape and take energy away, cooling the skin.","Why does the temperature of boiling water stay at about 100°C while it boils?|The added energy breaks attractions between particles instead of raising temperature.","Describe the full cycle solid → liquid → vapor → liquid → solid for water and state when energy is absorbed or released.|Melting and evaporation absorb energy; condensation and freezing release energy."],
 act:'Heat ice in a pan (with an adult) and record the temperature every minute until it boils. Graph temperature vs. time and label melting and boiling.'},
'7-1-5':{F:[["The first step of a scientific investigation is stating the ____.","aim or problem","conclusion","results","materials"],["The part that lists what you need for the investigation is the ____.","materials and equipment","method","conclusion","aim"],["The step-by-step instructions are the ____.","method or procedure","results","aim","conclusion"],["The part that answers the aim based on data is the ____.","conclusion","materials","method","aim"]],
 C:["Write an aim for an investigation on how sunlight affects plant growth.|Possible: To find out whether the amount of sunlight affects the height of mongo seedlings.","Why must the method be written clearly?|So others can repeat the investigation and check the results.","What is the difference between results and conclusion?|Results are the data observed; the conclusion explains what the data shows about the aim.",["In an investigation on dissolving sugar in hot and cold water, which should stay the same?","amount of sugar and water","the water temperature","nothing","the result"]],
 E:["Plan a short investigation: Does salt water boil faster than tap water? Give aim, materials, method (3 steps), and how you will record results.|Answers vary; must include all parts and a fair test.","Why should an investigation be repeated more than once?|To make results reliable and reduce the effect of errors.","Identify the independent, dependent, and controlled variables in testing whether fertilizer amount affects plant height.|Independent: amount of fertilizer; dependent: plant height; controlled: plant type, water, sunlight, pot size."],
 act:'Do a short investigation in groups: Which paper towel brand absorbs the most water? Write the aim, materials, method, results table, and conclusion.'},
'7-1-6':{F:[["The SI unit of length is the ____.","meter","kilogram","second","liter"],["The SI unit of mass is the ____.","kilogram","meter","newton","liter"],["Which tool measures volume of a liquid accurately?","graduated cylinder","ruler","balance","thermometer"],["Which tool measures temperature?","thermometer","stopwatch","balance","ruler"]],
 C:["Convert 2.5 kg to grams.|2,500 g","Convert 350 cm to meters.|3.5 m","Why should you read a graduated cylinder at eye level?|To avoid parallax error and read the bottom of the meniscus accurately.","Why do scientists organize data in tables?|To record results clearly and see patterns easily."],
 E:["A learner measured a pencil three times: 15.2 cm, 15.3 cm, 15.2 cm. What is the average, and why measure more than once?|15.23 cm; repeated measurements improve accuracy and reliability.","Design a data table for measuring the temperature of water every 2 minutes for 10 minutes.|Columns: time (min) 0, 2, 4, 6, 8, 10 and temperature (°C).","Explain the difference between accuracy and precision.|Accuracy is closeness to the true value; precision is how close repeated measurements are to each other."],
 act:'Measure the length, mass and volume of three objects (e.g., a stone, a cup of water, a book) using the proper tools. Record in a table with units.'},
'7-1-7':{F:[["In salt water, the salt is the ____.","solute","solvent","solution","precipitate"],["In salt water, the water is the ____.","solvent","solute","mixture","suspension"],["Water is called the universal solvent because ____.","it dissolves many substances","it is everywhere","it is blue","it never dissolves anything"],["A solution is a ____ mixture.","homogeneous","heterogeneous","solid","layered"]],
 C:["Identify the solute and solvent in juice made from powder and water.|solute: juice powder; solvent: water","In air, which gas is the solvent?|nitrogen (the gas present in the largest amount)",["Which is a solution?","vinegar","sand and water","oil and water","halo-halo"],"What is the difference between a solute and a solvent?|The solute dissolves; the solvent does the dissolving and is usually present in a larger amount."],
 E:["Name a solution where the solvent is not a liquid. Identify its parts.|Examples: air (solvent nitrogen, solutes oxygen and others); brass (solvent copper, solute zinc).","Why does nail polish remover (acetone) remove nail polish but water does not?|The polish dissolves in acetone but not in water; different solvents dissolve different solutes.","Explain using particles how a solute dissolves in a solvent.|Solvent particles surround and pull solute particles apart, spreading them evenly."],
 act:'Mix different materials (salt, sugar, sand, oil, coffee) with water. Classify which form solutions and identify the solute and solvent in each.'},
'7-1-8':{gen:['conc'],F:[["A solution with a small amount of solute is ____.","dilute","concentrated","saturated","supersaturated"],["A solution with a large amount of solute is ____.","concentrated","dilute","pure","empty"]],
 C:["Why is it useful to express concentration as a number?|It tells exactly how much solute is present, which matters in medicine, cooking, and industry."],
 E:["A label says 5% acetic acid (by volume) for vinegar. What does this mean?|There are 5 mL of acetic acid in every 100 mL of vinegar."],
 act:'Prepare three sugar solutions with 5 g, 10 g and 20 g of sugar in 100 mL of water. Compute the concentration of each and compare the taste (do not taste in the lab; use food-safe cups at home).'},
'7-1-9':{F:[["Sugar dissolves faster in ____.","hot water","ice water","cold water","oil"],["Stirring makes a solute dissolve ____.","faster","slower","not at all","only in oil"],["Which dissolves faster?","fine sugar","sugar cubes","rock sugar","all the same"],"Name one factor that affects how fast a solute dissolves.|temperature, stirring, particle size (any one)"],
 C:["Why does powdered milk dissolve faster than milk lumps?|Smaller particles have more surface area in contact with the solvent.","Why can more sugar dissolve in hot water than in cold water?|Hot water particles move faster and pull apart more solute particles; solubility usually increases with temperature.","What is a saturated solution?|A solution that cannot dissolve any more solute at that temperature.",["Which gas dissolves better in cold water?","carbon dioxide in soda","none","all gases dissolve better in hot water","oxygen in boiling water"]],
 E:["Plan a fair test to see how temperature affects solubility of salt.|Use same amount of water at different temperatures; add salt spoon by spoon with stirring until no more dissolves; count spoons.","Why do fish sometimes die in very warm ponds?|Less oxygen dissolves in warm water.","Explain why soda goes flat faster when warm.|Gases are less soluble at higher temperatures, so carbon dioxide escapes faster."],
 act:'Test how temperature, stirring, and particle size affect how fast sugar dissolves. Change one factor at a time and time each trial.'},
'7-1-10':{F:[["Acids turn blue litmus paper ____.","red","blue","green","yellow"],["Bases turn red litmus paper ____.","blue","red","black","white"],["Which is an acid found at home?","vinegar","soap","baking soda","toothpaste"],["Which is a base found at home?","soap solution","calamansi juice","vinegar","soft drinks"]],
 C:["Salt water does not change the color of either litmus paper. Why?|It is neutral (a salt solution).","What is the pH of a neutral solution?|7","Classify: calamansi juice, toothpaste, distilled water.|acid, base, neutral",["A pH of 2 is ____.","strongly acidic","neutral","strongly basic","weakly basic"]],
 E:["Make a natural indicator from violet eggplant skin or red cabbage. What colors would you expect for vinegar and soap?|Acids turn it pink/red; bases turn it green/yellow (colors vary).","Why should you never taste or touch unknown solutions to test if they are acids?|Strong acids and bases can burn and poison.","Why is the stomach acidic, and how do antacids help?|Stomach acid helps digest food; antacids are bases that neutralize excess acid."],
 act:'Use litmus paper or a homemade indicator (boiled violet cabbage or eggplant water) to test solutions at home and school. Classify each as acid, base, or neutral.'},
'7-1-11':{F:[["Before using laboratory equipment, you should ____.","read instructions and ask the teacher","play with it first","use it without checking","take it home"],["When heating a test tube, point the open end ____.","away from people","toward your face","toward your classmates","upward to the ceiling light"],["Which should you wear when working with chemicals?","safety goggles","sunglasses","a cap","slippers"],"What should you do if you break glassware?|Tell the teacher; do not pick it up with bare hands."],
 C:["Why must you never smell chemicals directly?|Fumes may be harmful; use wafting with your hand instead.","How should you carry a microscope or heavy equipment?|With both hands, holding it close to your body.",["Which is the proper way to light an alcohol lamp?","use a lighter or match held to the wick, never another lit lamp","light it from another lit lamp","pour alcohol while lit","blow into it"],"Why should you clean and return equipment after use?|To keep it safe, working, and ready for the next class."],
 E:["Make five safety rules for your science laboratory.|Answers vary; e.g., wear goggles, no eating, report accidents, handle glass carefully, wash hands.","Explain what to do if a chemical spills on your skin.|Rinse with plenty of water immediately and tell the teacher.","Why do labs keep fire extinguishers and first-aid kits?|To respond quickly to accidents and prevent bigger harm."],
 act:'In pairs, practice using a graduated cylinder, a balance, an alcohol lamp (with teacher supervision), and a test tube holder. Check each other using a safety checklist.'},
'7-1-12':{F:[["Which part of a microscope holds the slide?","stage","eyepiece","base","arm"],["Which part do you look through?","eyepiece (ocular lens)","stage","diaphragm","base"],["Which part controls the amount of light?","diaphragm","coarse adjustment knob","arm","base"],["Which knob is used for sharp, fine focusing?","fine adjustment knob","coarse adjustment knob","revolving nosepiece","stage clip"]],
 C:["If the eyepiece is 10× and the objective is 40×, what is the total magnification?|400×","Why should you start with the low power objective?|It gives a wider view, making it easier to find the specimen.","How should a microscope be stored?|Covered, with the low power objective in place, stage lowered, and in a dry place.",["Which part connects the eyepiece to the objectives?","body tube","base","stage","diaphragm"]],
 E:["Why should you never use the coarse adjustment knob with the high power objective?|The lens may hit and break the slide.","List the steps to focus a specimen correctly.|Place slide, use low power, lower objective while watching from the side, focus up with coarse knob, then fine knob, then switch to higher power and use fine knob.","Explain why the image you see moves in the opposite direction when you move the slide.|The lenses invert the image."],
 act:'Label the parts of a compound microscope on a diagram. Then practice focusing on a slide of a printed letter “e” and draw what you see.'},
'7-1-13':{F:[["The part of the cell that controls its activities is the ____.","nucleus","cell membrane","cytoplasm","cell wall"],["The jelly-like material inside the cell is the ____.","cytoplasm","nucleus","chloroplast","vacuole"],["The part that controls what enters and leaves the cell is the ____.","cell membrane","nucleus","mitochondrion","ribosome"],["The organelle where food is made in plant cells is the ____.","chloroplast","mitochondrion","nucleus","vacuole"]],
 C:["Which organelle releases energy from food?|mitochondrion","Why do we stain onion cells with iodine?|to make cell parts like the nucleus easier to see","How do you make a wet mount of onion skin?|Place a thin layer on a slide, add a drop of water (or stain), and cover with a cover slip at an angle to avoid bubbles.",["In a cheek cell slide, which part would you NOT see?","chloroplast","nucleus","cell membrane","cytoplasm"]],
 E:["Why are there many mitochondria in muscle cells?|Muscle cells need a lot of energy.","Draw (describe) an onion cell under high power and label the parts you can see.|cell wall, cell membrane (close to wall), cytoplasm, nucleus","Why can’t mitochondria be easily seen with a school microscope?|They are very small; they need higher magnification and special stains."],
 act:'Prepare wet mounts of onion skin (iodine stain) and cheek cells (with teacher supervision). Observe under low and high power and draw labeled diagrams.'},
'7-1-14':{F:[["An organism made of only one cell is ____.","unicellular","multicellular","a tissue","an organ"],["Which is unicellular?","bacterium","human","mango tree","dog"],["Which is multicellular?","human","bacterium","amoeba","paramecium"],"Can a unicellular organism carry out all life processes?|Yes."],
 C:["Give two examples of unicellular organisms.|bacteria, amoeba, paramecium, yeast (any two)","What is one advantage of being multicellular?|Cells can specialize for different jobs, and the organism can grow larger.",["Yeast used in bread is ____.","unicellular","multicellular","not living","a plant"],"Why can some unicellular organisms cause disease?|Some bacteria and protists invade the body and harm cells."],
 E:["Compare how a unicellular and a multicellular organism get food.|Unicellular: the one cell takes in food directly; multicellular: specialized organs and systems digest and transport food to all cells.","Why is a multicellular organism more affected if many of its cells are damaged?|Specialized cells depend on each other; damage to one tissue affects others.","Name one useful unicellular organism and its use.|Yeast for bread; Lactobacillus for yogurt; bacteria for nata de coco (any one)."],
 act:'Observe pond water or yogurt (with a little water) under the microscope. Draw any unicellular organisms you see and compare them with your onion cell drawing.'},
'7-1-15':{F:[["Which part is found in plant cells but not in animal cells?","cell wall","nucleus","cytoplasm","cell membrane"],["Plant cells have chloroplasts so they can ____.","make food","move","digest bones","pump blood"],["Plant cells usually have ____ vacuole(s).","one large","many tiny","no","two small"],["Which shape is typical of plant cells?","rectangular/boxy","always round","star-shaped","no fixed shape"]],
 C:["Name three organelles found in both plant and animal cells.|nucleus, cell membrane, cytoplasm, mitochondria (any three)","Why do plant cells need a cell wall?|for support and protection, to keep their shape","Why do animal cells not need chloroplasts?|Animals get food by eating; they do not make their own food.",["Centrioles are usually found in ____.","animal cells","plant cells only","both equally","neither"]],
 E:["Use a Venn diagram to compare plant and animal cells.|Plant only: cell wall, chloroplasts, large vacuole; both: nucleus, membrane, cytoplasm, mitochondria; animal only: centrioles, small vacuoles.","Why do plants wilt when they lack water? Relate to the vacuole.|The vacuole loses water and the cell loses firmness.","A cell has a cell wall but no chloroplasts. Could it be a plant cell? Explain.|Yes, e.g., a root cell; roots underground do not need chloroplasts."],
 act:'Compare your onion cell and cheek cell drawings. Make a Venn diagram of plant and animal cell parts.'},
'7-2-0':{F:[["Cell division for growth and repair is ____.","mitosis","meiosis","fertilization","photosynthesis"],["Cell division that produces sex cells is ____.","meiosis","mitosis","respiration","digestion"],["Mitosis produces ____ cells that are identical to the parent cell.","2","4","8","1"],"Why does a wound heal?|Cells divide by mitosis to replace damaged cells."],
 C:["How many daughter cells does meiosis produce, and how do they compare with the parent cell?|4 cells, each with half the number of chromosomes","Name the stages of mitosis in order.|prophase, metaphase, anaphase, telophase (then cytokinesis)",["In which body part is mitosis very active?","skin and bone marrow","inside a tooth’s enamel","hair after it is cut","nails after they are trimmed"],"Why must cells copy their DNA before mitosis?|So each new cell gets a complete set of chromosomes."],
 E:["Compare mitosis and meiosis in a table (purpose, number of cells, chromosome number).|Mitosis: growth/repair, 2 cells, same number; meiosis: sex cells, 4 cells, half the number.","What can happen if mitosis is not controlled?|Cells can divide too much and form tumors (cancer).","Why is meiosis important for keeping the chromosome number the same from generation to generation?|Sex cells have half, so fertilization restores the full number."],
 act:'Make a flip book or paper model showing the stages of mitosis using yarn or pipe cleaners as chromosomes.'},
'7-2-1':{F:[["Offspring get genetic information from ____.","both parents","the mother only","the father only","the environment only"],["The joining of a sperm cell and an egg cell is ____.","fertilization","mitosis","meiosis","digestion"],["Sex cells are produced by ____.","meiosis","mitosis","photosynthesis","respiration"],"How many chromosomes are in a human body cell?|46"],
 C:["How many chromosomes are in a human egg or sperm cell?|23","Why do siblings look different even with the same parents?|Meiosis and fertilization mix genes in different combinations.","What is a zygote?|the fertilized egg cell formed when sperm and egg join",["Why do sex cells have half the chromosomes?","so the zygote will have the full number after fertilization","to make cells smaller","so they can do photosynthesis","so they live longer"]],
 E:["Explain how meiosis and fertilization create variation in offspring.|Meiosis shuffles and separates chromosomes; fertilization combines genes from two parents.","Why is variation important for a species?|It helps some individuals survive changes in the environment.","Trace the chromosome number from parent cells to sex cells to zygote in humans.|46 → 23 (sex cells) → 46 (zygote)"],
 act:'Use colored paper strips as chromosomes. Model how a parent cell (4 chromosomes) makes sex cells (2 chromosomes) and how fertilization forms a zygote (4).'},
'7-2-2':{F:[["Reproduction that needs two parents is ____.","sexual","asexual","budding","fragmentation"],["Reproduction from one parent only is ____.","asexual","sexual","fertilization","pollination"],["Offspring from asexual reproduction are ____.","identical to the parent","very different from the parent","from two parents","always weaker"],["Which is asexual reproduction?","a potato growing from its eye","a chicken hatching from a fertilized egg","a baby born to two parents","a mango seed from pollinated flower"]],
 C:["Give two examples of asexual reproduction in plants.|stem cuttings (e.g., kamote, malunggay), budding, runners, tubers (any two)","Why do farmers use cuttings to grow sweeter mangoes or calamansi?|Asexual methods produce plants identical to the parent with the desired traits.",["Yeast reproduces by ____.","budding","seeds","fertilization","spores only"],"What is one advantage of sexual reproduction?|It produces variation that helps survival in changing environments."],
 E:["Compare sexual and asexual reproduction in terms of number of parents, variation, and speed.|Sexual: 2 parents, variation, slower; asexual: 1 parent, identical, faster.","Why might a field of identical banana plants be at risk from one disease?|They have no variation, so a disease that kills one can kill all.","Explain why some organisms can reproduce both sexually and asexually.|It combines fast growth (asexual) with variation (sexual) depending on conditions."],
 act:'Grow plants from stem cuttings (kamote, malunggay, or San Francisco) and from seeds (mongo). Compare how fast they grow and how similar they are to the parent.'},
'7-2-3':{F:[["Which is the smallest level of biological organization?","cell","tissue","organ","organism"],["A group of similar cells working together is a ____.","tissue","organ","system","population"],["The heart is an example of an ____.","organ","organism","tissue","ecosystem"],["All the populations living in one area form a ____.","community","biosphere","cell","organ"]],
 C:["Arrange in order: organ, cell, organism, tissue, organ system.|cell → tissue → organ → organ system → organism","What is the difference between a population and a community?|A population is one species in an area; a community is all species living together there.","Give an example of an ecosystem in the Philippines.|coral reef, mangrove forest, rice field, rainforest (any)",["The biosphere is ____.","all parts of Earth where life exists","one organ","one population","one cell"]],
 E:["Use the example of a tilapia to trace levels from cell to biosphere.|muscle cell → muscle tissue → heart → circulatory system → tilapia → tilapia population → pond community → pond ecosystem → biosphere","How does damage at one level affect higher levels? Give an example.|Polluting a river kills fish populations, which affects the whole community and the people who depend on it.","Why is the ecosystem level more than just a community?|It includes non-living factors like water, soil, and sunlight."],
 act:'Make a labeled diagram or flow chart showing the levels of organization from a cell to the biosphere using a local example (e.g., a carabao or a rice plant).'},
'7-2-4':{F:[["Organisms that make their own food are ____.","producers","consumers","decomposers","carnivores"],["The first trophic level in a food pyramid is made of ____.","producers","top predators","decomposers","herbivores"],["A herbivore is a ____.","primary consumer","producer","tertiary consumer","decomposer"],["Which is at the top of a food pyramid?","top predator (e.g., eagle)","grass","grasshopper","algae"]],
 C:["In the chain grass → grasshopper → frog → snake → eagle, what trophic level is the frog?|third trophic level (secondary consumer)","Why are there usually fewer top predators than producers?|Less energy is available at higher levels.",["Which organism is a secondary consumer?","a frog that eats insects","rice","a carabao eating grass","bacteria"],"What do decomposers do in an ecosystem?|They break down dead organisms and return nutrients to the soil."],
 E:["Why is a food pyramid shaped like a pyramid?|Energy decreases at each higher level, so fewer organisms can be supported.","Draw (describe) a food pyramid for a rice field ecosystem.|Base: rice; next: rice insects/ snails; next: frogs; top: snakes/herons","Explain what happens to a food pyramid if most frogs are killed by pesticides.|Insects may increase and damage crops; snakes may decrease due to less food."],
 act:'Using pictures of local organisms, build a food pyramid on manila paper and label each trophic level.'},
'7-2-5':{gen:['tenpct'],F:[["About how much energy is passed to the next trophic level?","about 10%","about 90%","100%","0%"],["Most energy at each level is lost as ____.","heat","light","sound","water"],["The original source of energy in most food pyramids is the ____.","Sun","soil","water","moon"]],
 C:["Why can a field of rice feed more people than if the rice were fed to pigs first?|Energy is lost at each level; eating producers directly uses more of the energy."],
 E:["Explain why food chains rarely have more than four or five levels.|Too little energy remains at higher levels to support more consumers."],
 act:'Use 1,000 beans to represent energy from the Sun captured by plants. Pass 10% to each level of a food pyramid and record how much energy reaches the top.'},
'7-2-6':{F:[["A force is a ____.","push or pull","type of energy","kind of matter","unit of mass"],["The SI unit of force is the ____.","newton","kilogram","meter","joule"],["Which tool measures force?","spring scale","ruler","thermometer","beaker"],["Which is an example of a force?","pushing a cart","the color of a ball","the length of a table","a temperature reading"]],
 C:["Name two types of contact forces and two non-contact forces.|Contact: friction, applied force, normal force, tension; non-contact: gravity, magnetic, electric force","What force pulls a falling mango to the ground?|gravity (weight)","Why does a ball rolling on grass stop?|friction slows it down",["Forces always act ____.","between two objects","on one object alone","only on living things","only in space"]],
 E:["A spring scale reads 5 N when holding a bag. What does this measure, and what is the bag’s approximate mass? (g ≈ 10 N/kg)|its weight; about 0.5 kg","Explain how friction can be both useful and a problem. Give examples.|Useful: walking, brakes; problem: wears out tires, wastes energy as heat.","Identify the forces acting on a book resting on a table.|gravity (down) and normal force from the table (up)"],
 act:'Use a spring scale (or rubber band and ruler) to measure the force needed to pull a box on different surfaces. Record and compare.'},
'7-2-7':{F:[["When forces on an object are balanced, the object ____.","stays at rest or moves at constant velocity","speeds up","changes direction","falls"],["A falling fruit shows ____ forces.","unbalanced","balanced","no","equal"],["A man standing still has ____ forces acting on him.","balanced","unbalanced","no","only upward"],"Is a car moving at a constant speed on a straight road under balanced or unbalanced forces?|balanced"],
 C:["Why is a car speeding up an example of unbalanced forces?|The forward force is greater than friction and air resistance, so it accelerates.","A tug-of-war rope does not move. What can you say about the forces?|They are balanced (equal and opposite).",["Which shows unbalanced forces?","a jeepney braking to stop","a lamp hanging still","a book on a shelf","a boat floating still"],"Why does a box resting on a ramp not slide down?|Friction balances the part of gravity pulling it down the ramp."],
 E:["Two teams pull with 500 N and 450 N. What is the net force and which way does the rope move?|50 N toward the 500 N team","Explain how a parachute helps a skydiver reach constant speed.|Air resistance increases until it equals weight; forces balance and speed becomes constant.","Give an everyday example of balanced forces where the object is moving.|a bicycle moving at steady speed on level road"],
 act:'Play a mini tug-of-war with spring scales. Record forces when the rope is still and when it moves. Classify as balanced or unbalanced.'},
'7-2-8':{F:[["A free-body diagram shows ____.","the forces acting on an object","the parts of a cell","a food chain","the water cycle"],["In a free-body diagram, forces are drawn as ____.","arrows","circles","dots only","squares"],["The length of an arrow shows the force’s ____.","size (magnitude)","color","mass","temperature"],["The direction of the arrow shows the force’s ____.","direction","speed","mass","size only"]],
 C:["Draw (describe) a free-body diagram of a book on a table.|Box with arrow down (weight) and arrow up (normal force) of equal length.","Draw (describe) the forces on a falling coconut with air resistance.|Long arrow down (weight), short arrow up (air resistance); unbalanced downward.",["In a balanced free-body diagram, the arrows ____.","are equal in length and opposite","point the same way","are missing","are different colors"],"What forces act on a hanging lamp?|weight (down) and tension (up)"],
 E:["Draw (describe) a free-body diagram for a car speeding up and explain how it shows unbalanced forces.|Forward force arrow longer than friction arrow; weight and normal equal; net force forward.","A box is pushed with 30 N right; friction is 10 N left. What is the net force?|20 N to the right","Why is it important to draw arrows to scale?|So the diagram correctly shows which forces are larger and the direction of the net force."],
 act:'Draw free-body diagrams for five situations: a book on a table, a hanging lamp, a falling ball, a car speeding up, and a box being pushed but not moving.'},
'7-2-9':{F:[["An unbalanced force can change an object’s ____.","speed or direction","color","mass","temperature"],["Kicking a ball that is at rest makes it ____.","start moving","stay still","disappear","get heavier"],["Which shows a change in direction?","a ball hit by a bat","a ball resting on the floor","a parked car","a hanging lamp"],"What happens when a moving object meets an unbalanced force in the opposite direction?|It slows down."],
 C:["Why does a jeepney turning a corner need a force?|A force is needed to change the direction of motion.","Give an example of an unbalanced force making something speed up.|pushing a cart harder; a car pressing the gas",["A ball rolling on a rough floor slows down because of ____.","friction","gravity pulling it forward","air pushing it forward","magnetism"],"Can an object keep moving without a force pushing it? Explain.|Yes; it keeps moving unless an unbalanced force (like friction) acts on it."],
 E:["Explain why passengers lean when a jeepney turns suddenly.|Their bodies tend to keep moving straight while the jeepney changes direction.","Describe three ways an unbalanced force can change motion, with examples.|speed up (push a cart), slow down (brakes), change direction (hit a ball)","Why does a satellite keep moving in orbit?|Gravity keeps changing its direction, pulling it into a curved path."],
 act:'Roll a marble on a table. Use a ruler to push it from different directions. Record how its speed and direction change.'},
'7-2-10':{gen:['dispdist'],F:[["Distance is the ____.","total length of the path traveled","straight-line change in position","speed with direction","time taken"],["Displacement is the ____.","straight-line change in position from start to end, with direction","total path length","time taken","speed only"],["Displacement needs a ____ point.","reference","rest","boiling","melting"]],
 C:["A learner walks around a 400-m track once and returns to start. What are the distance and displacement?|distance 400 m; displacement 0 m"],
 E:["Can displacement be greater than distance? Explain.|No; the straight-line path is the shortest, so displacement is less than or equal to distance."],
 act:'Walk a path around the school (e.g., 20 m east, 15 m north). Measure the distance walked and the displacement from start to end using a measuring tape.'},
'7-2-11':{gen:['speedvel'],F:[["Speed is a ____ quantity.","scalar","vector","directionless vector","negative"],["Velocity is speed with ____.","direction","mass","color","temperature"],["Which is a velocity?","60 km/h north","60 km/h","60 km","60 minutes"]],
 C:["Two jeepneys move at 40 km/h, one north and one south. Do they have the same speed? Same velocity?|same speed; different velocities"],
 E:["A car goes around a curve at constant speed. Is its velocity constant? Explain.|No; its direction changes, so velocity changes."],
 act:'Time a classmate walking 10 m in different directions. Compute speed and write the velocity with direction.'},
'7-2-12':{gen:['dtgraph'],F:[["On a distance-time graph, a straight sloping line means ____.","uniform (constant) velocity","the object is at rest","the object is speeding up","the object is slowing down"],["A flat horizontal line on a distance-time graph means the object is ____.","at rest","moving fast","speeding up","turning"],["The slope of a distance-time graph shows ____.","speed","mass","force","temperature"]],
 C:["Which object is faster: one whose distance-time line is steeper or less steep?|the steeper one"],
 E:["Sketch (describe) a distance-time graph for a jeepney that moves at constant speed, stops for passengers, then moves again.|Straight sloping line, then flat line, then sloping line again."],
 act:'Record the time a toy car or a walking learner takes to pass marks every 1 m. Plot a distance-time graph and find the speed from the slope.'},
'7-3-0':{F:[["Temperature measures ____.","the average kinetic energy of particles","the total energy of a body","the amount of matter","the color of an object"],["Heat is energy that flows from ____.","a hotter object to a colder object","a colder to a hotter object","nowhere","only in metals"],["The SI unit of heat (energy) is the ____.","joule","degree Celsius","newton","meter"],["Which instrument measures temperature?","thermometer","calorimeter only","ruler","balance"]],
 C:["A bathtub of warm water and a cup of boiling water: which has more heat energy? Which has higher temperature?|The bathtub can have more total heat energy; the cup has higher temperature.","Why does a metal spoon in hot soup become hot?|Heat flows from the soup to the spoon.",["When two objects reach the same temperature, heat ____.","stops flowing between them","keeps flowing faster","flows to the colder one","becomes light"],"Is cold a form of energy?|No; cold is the absence of heat (lower thermal energy)."],
 E:["Explain why heat and temperature are not the same, using an example.|Temperature is the average energy of particles; heat is energy transferred. A big pot at 50°C can transfer more heat than a small cup at 90°C.","Why does it take longer to boil a full pot than half a pot of water?|More water needs more heat to raise its temperature.","What happens to particle motion when heat is added to water?|Particles move faster, increasing temperature."],
 act:'Mix equal amounts of hot and cold water and measure the final temperature. Then mix different amounts. Explain the results using heat and temperature.'},
'7-3-1':{F:[["Heat transfer through direct contact is ____.","conduction","convection","radiation","evaporation"],["Heat transfer by moving liquids or gases is ____.","convection","conduction","radiation","reflection"],["Heat from the Sun reaches Earth by ____.","radiation","conduction","convection","boiling"],["Which is a good conductor of heat?","metal","wood","plastic","cloth"]],
 C:["Why do cooking pots have wooden or plastic handles?|They are poor conductors, so they protect hands from heat (advantageous use of insulators).","Give one disadvantage of conduction at home.|e.g., heat from a hot pan burning a hand; heat leaking through a metal roof into a house.","Why do houses with light-colored roofs stay cooler?|Light colors reflect radiation; dark colors absorb more.",["Which is an advantageous use of convection?","an electric fan or aircon circulating air","a burnt hand","a melted plastic handle","a cracked glass"]],
 E:["Explain how a thermos keeps drinks hot using conduction, convection and radiation.|Vacuum stops conduction and convection; shiny surfaces reduce radiation.","Why are clay pots (palayok) good for cooking rice slowly?|Clay heats evenly and holds heat; it conducts heat slowly.","Give one disadvantageous example of radiation and a way to reduce it.|Sunlight heating a classroom; use curtains, trees, or reflective roofing."],
 act:'Place a metal spoon, plastic spoon and wooden spoon in hot water. After 1 minute, carefully touch the handles. Rank them by conduction and explain uses at home.'},
'7-3-2':{F:[["In conduction, heat passes from particle to particle by ____.","collisions/vibrations","flowing water","light rays","sound waves"],["In convection, warm fluid rises because it is ____.","less dense","heavier","colder","solid"],["Which state of matter cannot have convection?","solid","liquid","gas","none"]],
 C:["Use the particle model to explain why metal conducts heat well.|Metal particles are close together and have free electrons that pass energy quickly.","Describe a convection current in a pot of boiling water.|Water at the bottom heats, expands, rises; cooler water sinks to replace it, forming a loop.","Why are gases poor conductors of heat?|Gas particles are far apart and collide less often.",["Which explains sea breeze?","convection currents in air","conduction through sand","radiation from the Moon","boiling of sea water"]],
 E:["Why is the freezer compartment usually at the top of a refrigerator?|Cold air sinks, creating a convection current that cools the whole fridge.","Explain why trapped air in a jacket keeps you warm.|Air is a poor conductor, and trapped air cannot form convection currents.","Using the particle model, explain why heating one end of a metal rod eventually makes the other end hot.|Particles at the hot end vibrate faster and pass energy to neighbors along the rod."],
 act:'Put a few drops of food coloring at the bottom of a beaker of water and gently heat one side. Observe and draw the convection current. Explain using particles.'},
'7-3-3':{F:[["A device that changes heat energy into electrical energy can be ____.","a thermoelectric generator","a light bulb","a fan","a speaker"],["Geothermal power plants use ____.","heat from inside the Earth","wind","sunlight on panels","tides"],["Which Philippine region is known for geothermal power?","Leyte (e.g., Tongonan)","Metro Manila business district","Batanes only","Marikina River"]],
 C:["How does a geothermal power plant make electricity?|Steam from hot underground water turns turbines connected to generators.","What is a thermoelectric (Peltier/Seebeck) device?|A device that produces electricity when there is a temperature difference across it.","Why is geothermal energy important for the Philippines?|The country has many volcanic areas, so it can use local, renewable heat energy.",["Where might a thermoelectric device be useful?","a cooking stove that also charges a phone","a candle in the wind","an ice cube","a plastic cup"]],
 E:["Using secondary sources, describe one innovative device that turns heat into electricity and how it works.|Answers vary; e.g., thermoelectric stove chargers, waste-heat recovery in factories.","Give one advantage and one limitation of geothermal energy.|Advantage: renewable, low emissions; limitation: only in certain locations, possible release of gases.","How could waste heat from factories or vehicles be used?|Capture it with heat exchangers or thermoelectric devices to produce electricity or warm water."],
 act:'Research one device or power plant that turns heat into electricity (e.g., a Philippine geothermal plant). Make a one-page infographic explaining how it works. Credit your sources.'},
'7-3-4':{F:[["A fault is a ____.","break in Earth’s crust where rocks have moved","river bend","volcano crater","type of rock"],["In a normal fault, the hanging wall moves ____ relative to the footwall.","down","up","sideways only","not at all"],["In a reverse fault, the hanging wall moves ____.","up","down","sideways only","nowhere"],["In a strike-slip fault, the blocks move ____.","horizontally past each other","straight up","straight down","in circles"]],
 C:["What kind of stress causes a normal fault?|tension (pulling apart)","What kind of stress causes a reverse (thrust) fault?|compression (pushing together)","What is a thrust fault?|a reverse fault with a low-angle fault plane",["The Philippine Fault Zone is mainly a ____ fault.","strike-slip","normal","reverse","no"]],
 E:["Classify a fault where the fault plane is steep and the hanging wall moved down.|normal fault","Explain how the angle of the fault plane helps classify faults.|Steep planes with dip-slip may be normal or reverse; low-angle reverse faults are thrust faults; vertical planes with horizontal slip are strike-slip.","Model the three fault types with clay or sponge blocks and describe each movement.|Answers vary; must show pulling apart, pushing together, and sliding past."],
 act:'Use two blocks of foam, clay, or layered paper to model normal, reverse, and strike-slip faults. Label the hanging wall, footwall, and direction of slip.'},
'7-3-5':{F:[["Earthquakes are caused mainly by ____.","sudden movement along faults","strong winds","heavy rain","the Moon"],["The energy of an earthquake travels as ____.","seismic waves","light waves","sound only","water"],["The Philippines has many earthquakes because it lies along the ____.","Pacific Ring of Fire","equator only","Arctic Circle","Sahara Desert"]],
 C:["Explain the elastic rebound idea of how faults cause earthquakes.|Rocks bend as stress builds; when stress exceeds friction, they suddenly slip and release energy as waves.","Name two active faults or trenches in the Philippines.|Philippine Fault Zone, Valley Fault System, Philippine Trench, Manila Trench (any two)","Why are strike-slip and reverse (thrust) faults common in the Philippines?|The Philippine Sea Plate and Eurasian Plate push and slide against each other.",["Which model best shows how a fault produces an earthquake?","two blocks held by friction that suddenly slip","a balloon popping","boiling water","a spinning top"]],
 E:["Using a map, explain why the Philippine Fault Zone runs from Luzon to Mindanao.|It accommodates sideways movement caused by plate motion; it is a long strike-slip zone through the islands.","Why can earthquakes happen in places far from plate boundaries?|Faults inside plates can also store and release stress.","Make (describe) a model showing how friction causes stored energy along a fault.|Answers vary; e.g., pulling a block with a rubber band until it jerks forward."],
 act:'Model an earthquake: pull a brick or block with a rubber band across sandpaper. Observe how energy builds up and is suddenly released. Relate to faults in the Philippines.'},
'7-3-6':{F:[["The amount of energy released by an earthquake is its ____.","magnitude","intensity","depth","epicenter"],["The strength of shaking felt at a place is the earthquake’s ____.","intensity","magnitude","focus","duration only"],["In the Philippines, intensity is reported using the ____.","PHIVOLCS Earthquake Intensity Scale (PEIS)","PAGASA wind signals","Richter only","pH scale"],"Which causes more damage: magnitude 4 or magnitude 7?|magnitude 7"],
 C:["Why can the same earthquake have different intensities in different towns?|Intensity depends on distance from the epicenter, ground type, and building quality.","Each whole number increase in magnitude releases about how much more energy?|about 32 times more energy",["Which community is likely to suffer more in a strong earthquake?","one with poorly built houses on soft soil","one with well-built houses on hard rock","one far from the epicenter","one with earthquake drills"],"Give two effects of a strong earthquake on a community.|collapsed buildings, landslides, injuries, liquefaction, tsunami (any two)"],
 E:["Compare the effects of a magnitude 5 earthquake in a remote area and in a crowded city.|The city may suffer more damage and casualties due to many buildings and people.","Why does soft, wet ground (like reclaimed land) shake more?|Seismic waves are amplified in soft soils; liquefaction may occur.","Suggest two ways communities can reduce earthquake damage.|follow building codes, retrofit structures, hold drills, avoid building on faults"],
 act:'Build simple model houses of paper or straws on a tray of sand and on a tray of gelatin. Shake gently and strongly. Compare the effects to explain magnitude and ground type.'},
'7-3-7':{F:[["Which agency provides the FaultFinder tool in the Philippines?","PHIVOLCS","PAGASA","DepEd","DOH"],["The FaultFinder helps you find ____.","how far your location is from an active fault","the weather","the nearest school","rice prices"],["A place near an active fault has ____ risk of strong ground shaking.","higher","lower","no","the same as everywhere"]],
 C:["What information should you record when using FaultFinder for your community?|the nearest active fault, its name, and the distance from your location","Besides distance from a fault, what else affects earthquake risk?|soil type, building quality, population, and preparedness","Why should you use reliable sources like PHIVOLCS instead of social media rumors?|PHIVOLCS gives scientifically checked information."],
 E:["Assess your community’s earthquake risk using distance to the nearest fault and two other factors.|Answers vary; must use distance and two other factors with reasons.","Recommend two actions your school should take based on its distance from an active fault.|e.g., regular drills, checking building safety, emergency kits, evacuation plan","Why does living far from a fault not mean you are completely safe?|Strong earthquakes can cause shaking far away; other faults may be unmapped."],
 act:'Use PHIVOLCS FaultFinder (or a hazard map provided by the teacher) to find the nearest active fault to your school. Record the distance and write a short risk assessment.'},
'7-3-8':{F:[["The point underground where an earthquake starts is the ____.","focus (hypocenter)","epicenter","fault line","trench"],["The point on the surface directly above the focus is the ____.","epicenter","focus","crater","core"],["A tsunami is most likely caused by ____.","an earthquake under the sea that moves the seafloor","strong winds","heavy rain","a full moon"]],
 C:["Why does not every undersea earthquake cause a tsunami?|The seafloor must move vertically enough to displace a large volume of water; strike-slip or deep quakes may not.","Explain the difference between magnitude and intensity using your model.|Magnitude is the energy at the source (one value); intensity is shaking at each location (varies with distance).","How can you model an epicenter using a box of sand?|Tap a point underneath (focus) and mark the spot directly above on the surface (epicenter)."],
 E:["Design a model to show how vertical seafloor movement creates a tsunami.|Answers vary; e.g., a tray of water with a board lifted suddenly at the bottom.","Why is intensity usually highest near the epicenter?|Seismic waves lose energy as they travel farther.","Explain why shallow earthquakes usually cause more surface damage than deep ones.|Shallow quakes are closer to the surface, so waves lose less energy before reaching it."],
 act:'In groups, build models: (a) a sand box to show focus and epicenter, (b) a tray of water with a movable board to show how seafloor movement can create a tsunami.'},
'7-3-9':{F:[["During an earthquake, you should ____.","duck, cover, and hold","run outside immediately","use the elevator","stand near windows"],["After the shaking stops, you should ____.","evacuate calmly to an open area following the plan","go back for your things","light a candle near gas leaks","use elevators"],["Which should be in an emergency go-bag?","water, food, flashlight, first-aid kit","video games","heavy furniture","a television"]],
 C:["Why should you stay away from windows during an earthquake?|Glass can break and cause injuries.","What should you check after an earthquake at home?|gas leaks, damaged wires, cracks, injuries","Why are earthquake drills important?|They train people to respond quickly and correctly."],
 E:["Make an earthquake plan for your family with three before, during, and after actions.|Answers vary; must include actions for all three phases.","Why should you expect aftershocks?|After a strong earthquake, smaller quakes can occur as rocks adjust.","Review your school’s evacuation plan and suggest one improvement.|Answers vary."],
 act:'Study your school or barangay disaster readiness plan. Practice “duck, cover, and hold” and the evacuation route, then list what went well and what needs improvement.'},
'7-3-10':{F:[["A tsunami is a ____.","series of large sea waves","single small wave","strong wind","heavy rain"],["A warning sign of a tsunami is ____.","the sea suddenly drawing back from the shore","a clear sky","a rainbow","cold weather"],["If you feel a strong earthquake near the coast, you should ____.","move to high ground immediately","go to the beach to watch","stay in a low area","wait for the waves"]],
 C:["Why are tsunamis very destructive to shoreline communities?|The waves carry huge amounts of water inland at high speed, destroying buildings and drowning people.","Why can the first tsunami wave not be the largest?|Tsunamis come in a series; later waves can be bigger.","How fast can tsunami waves travel in the deep ocean?|very fast — hundreds of kilometers per hour"],
 E:["Explain how an earthquake produces a tsunami from start to coast.|Seafloor moves vertically → water is displaced → waves travel fast in deep water → slow and grow tall near shore → flood the coast.","Why are mangroves helpful against tsunamis?|They reduce wave energy and protect the coast.","Describe how coastal communities can prepare for tsunamis.|warning systems, evacuation routes and drills, high-ground evacuation sites, coastal forests"],
 act:'Using a tray with sand and water, model a gentle slope (beach) and create waves by lifting a board. Observe how waves grow near the shore. Explain why tsunamis are dangerous.'},
'7-3-11':{F:[["Which agency issues tsunami information and warnings in the Philippines?","PHIVOLCS","PAGASA","DepEd","LTO"],["Tsunami warnings may be spread by ____.","sirens, radio, TV, text alerts, and local officials","rumors only","social media memes only","no one"],["When a tsunami warning is issued, residents near the coast should ____.","evacuate to high ground","go fishing","wait at the beach","ignore it"]],
 C:["Why do coastal barangays post tsunami evacuation signs?|To show people the fastest route to high ground.","What should a community do after a tsunami?|Wait for official all-clear, help the injured, avoid damaged buildings and floodwater, check on neighbors.","Why should people not return to the shore right after the first wave?|More waves may come."],
 E:["Evaluate your community’s tsunami readiness (signs, routes, drills).|Answers vary; must give evidence and suggestions.","Explain the role of local government units in tsunami response.|They spread warnings, lead evacuation, run shelters, and coordinate rescue and relief.","Why is natural warning (strong shaking, sea drawing back) important even if no official warning is heard?|Warnings may not arrive in time for nearby earthquakes; people must act immediately."],
 act:'Interview a barangay or disaster office official (or study the local DRRM plan) about tsunami alerts and evacuation. Make an evacuation map for your area.'},
'7-3-12':{F:[["Some sunlight that reaches Earth is ____ by clouds and the surface.","reflected","eaten","frozen","doubled"],["The atmosphere absorbs some of the Sun’s energy, which ____ it.","warms","freezes","darkens","dries"],["The ozone layer absorbs harmful ____ rays.","ultraviolet (UV)","radio","sound","visible"]],
 C:["What happens to sunlight when it reaches the atmosphere?|Some is reflected back to space, some is absorbed by the air and clouds, and some reaches and warms the surface.","Why is the sky blue?|Air molecules scatter blue light more than other colors.","How does the Earth’s surface warm the air above it?|The surface absorbs sunlight and gives off heat (infrared), which warms the air."],
 E:["Explain the natural greenhouse effect.|Greenhouse gases absorb heat given off by Earth and keep the planet warm enough for life.","Why are cloudy nights warmer than clear nights?|Clouds trap heat given off by the ground.","Why do sunsets look red or orange?|Light travels through more air; blue is scattered away, leaving red and orange."],
 act:'Place two thermometers in the sun: one in a clear covered jar and one in the open. Record temperatures every 5 minutes. Relate the result to how the atmosphere traps heat.'},
'7-3-13':{F:[["Earth’s axis is tilted at about ____.","23.5°","0°","45°","90°"],["Sunlight is most intense where it hits the surface ____.","directly (at a high angle)","at a low angle","at night","only at the poles"],["The tilt of the Earth causes ____.","seasons in many parts of the world","day and night only","tides","earthquakes"]],
 C:["Why do places near the equator receive strong sunlight all year?|The Sun’s rays hit them nearly directly throughout the year.","Using a flashlight, explain why tilted light is less intense.|The same light spreads over a larger area, so each part gets less energy.","Why is it summer in the Northern Hemisphere when it is winter in the Southern Hemisphere?|The Northern Hemisphere is tilted toward the Sun, receiving more direct light."],
 E:["Use a globe and a lamp to explain why the Philippines does not have four seasons.|It is near the equator, so sunlight intensity changes little during the year.","What would happen to seasons if Earth had no tilt?|There would be no seasons; sunlight would be about the same all year at each place.","Explain how intensity of sunlight affects temperature on different parts of Earth over a year.|More direct sunlight gives more energy per area and higher temperatures."],
 act:'Shine a flashlight on graph paper straight down and then at an angle. Count the squares lit. Use a tilted globe and lamp to show how sunlight intensity changes over a year.'},
'7-3-14':{F:[["Day length changes during the year because of Earth’s ____.","tilt and revolution","rotation only","size","color"],["Near the equator, day and night are ____ all year.","almost equal","very different","always 24 hours of day","always night"],["Places far from the equator have ____ days in summer.","longer","shorter","no","equal"]],
 C:["Why are summer days longer in Japan than in winter?|Japan’s hemisphere tilts toward the Sun in summer, so it spends more time in sunlight.","What are the equinoxes?|Days (around March 20 and September 22) when day and night are about equal everywhere.","Why does the Philippines have only small changes in day length?|It is near the equator."],
 E:["Use a model to explain why the North Pole has 24-hour daylight in June.|It is tilted toward the Sun, so it stays lit as Earth rotates.","Compare day length in Manila and in Stockholm in December.|Manila: about 11 hours; Stockholm: about 6 hours (much shorter).","Explain how day length affects farming in high-latitude countries.|Long summer days help crops grow fast; short winter days limit growing seasons."],
 act:'Use a lamp and a tilted globe. Rotate the globe and count how much of a circle of latitude stays lit in different positions of the orbit. Record day length changes.'},
'7-3-15':{F:[["A sea breeze blows from ____ during the day.","sea to land","land to sea","mountain to valley only","north to south always"],["A land breeze blows from ____ at night.","land to sea","sea to land","the Moon","up to down"],["The Philippines has two main monsoons: the ____.","habagat (southwest) and amihan (northeast)","El Niño and La Niña","tsunami and typhoon","summer and winter"]],
 C:["Why does a sea breeze form during the day?|Land heats faster than water; warm air over land rises and cooler air from the sea moves in.","What is the ITCZ?|The Intertropical Convergence Zone, a belt near the equator where trade winds meet, causing rising air, clouds and rain.","What weather does the habagat usually bring?|warm, moist air and heavy rains (about June to September)"],
 E:["Explain how uneven solar heating of land and sea causes monsoons.|Large land areas heat and cool differently from oceans across seasons, reversing wind patterns.","How does the ITCZ affect rainfall in the Philippines?|When it moves over the country, it brings cloudiness and rain.","Why is the amihan cooler and drier?|It comes from the cold Asian continent in the northeast (about November to February)."],
 act:'Heat a tray of sand and a tray of water under a lamp. Measure the temperatures every 5 minutes. Use incense smoke between them to show which way air moves. Relate to sea and land breezes.'}
});
